imageHint: "Lake Synevyr with small island in the middle",
    descriptionAdvanced: {
      de: "Der Synevyr-See, oft als das 'Meerauge' der Karpaten bezeichnet, ist der größte Bergsee der Ukraine und liegt auf einer Höhe von 989 Metern. Er entstand vor etwa 10.000 Jahren durch einen gewaltigen Erdrutsch, der den Flusslauf eines Gebirgsbachs blockierte. Der See erstreckt sich über eine Fläche von bis zu 7 Hektar und erreicht an seiner tiefsten Stelle eine Tiefe von etwa 24 Metern. In der Mitte des Sees befindet sich eine kleine Insel, die bei niedrigem Wasserstand wie die Pupille eines Auges wirkt, was dem See seinen Beinamen gab. Das Wasser ist kristallklar und beherbergt die seltene Bachforelle, obwohl die Temperatur selbst im Sommer selten über 11 Grad Celsius steigt. Umgeben ist der See von jahrhundertealten Tannen- und Buchenwäldern des Nationalparks Synevyr, der 1989 gegründet wurde. Eine bekannte Legende erzählt von der tragischen Liebe zwischen der Grafentochter Syn und dem Hirten Evyr, nach denen der See benannt sein soll. Heute ist er ein bedeutendes Denkmal der Natur und ein Magnet für Touristen, die Ruhe und unberührte Berglandschaften suchen.",
      hu: "A Szinevéri-tó, amelyet gyakran a Kárpátok 'tengerszemének' neveznek, Ukrajna legnagyobb hegyi tava, 989 méteres magasságban található. Körülbelül 10 000 évvel ezelőtt keletkezett egy hatalmas földcsuszamlás következtében, amely elzárta egy hegyi patak útját. A tó területe eléri a 7 hektárt, legnagyobb mélysége pedig körülbelül 24 méter. A tó közepén található egy apró sziget, amely alacsony vízállásnál úgy néz ki, mint egy szem szivárványhártyája, innen ered a beceneve. A víz kristálytiszta és otthont ad a ritka sebes pisztrángnak, bár hőmérséklete még nyáron is ritkán emelkedik 11 Celsius-fok fölé. A tavat a Szinevéri Nemzeti Park évszázados fenyő- és bükkerdői veszik körül, amelyet 1989-ben alapítottak. Egy népszerű legenda szerint a tó a grófkisasszony Szin és a pásztor Evir tragikus szerelméről kapta a nevét. Napjainkban a tó kiemelt természeti érték és népszerű turisztikai célpont, amely a nyugalom és az érintetlen hegyi táj jelképe.",
      ro: "Lacul Sinevir, supranumit adesea „Ochiul de Mare” al Carpaților, este cel mai mare lac montan din Ucraina, situat la o altitudine de 989 de metri. S-a format acum aproximativ 10.000 de ani în urma unei alunecări masive de teren care a blocat cursul unui pârâu montan. Lacul se întinde pe o suprafață de până la 7 hectare și atinge o adâncime maximă de circa 24 de metri. În centrul lacului se află o mică insulă care, la niveluri scăzute ale apei, seamănă cu pupila unui ochi, oferind lacului numele său simbolic. Apa este extrem de limpede și adăpostește păstrăvul de munte, deși temperatura acesteia rareori depășește 11 grade Celsius, chiar și în timpul verii. Lacul este înconjurat de păduri seculare de brad și fag din cadrul Parcului Național Sinevir, înființat în 1989. O legendă locală faimoasă povestește despre dragostea tragică dintre fiica unui conte, Syn, și un păstor, Evyr, de la care ar proveni numele lacului. Astăzi, acesta este un monument natural protejat și un magnet pentru turiștii care caută liniștea peisajelor montane virgine.",
      en: "Lake Synevyr, often called the 'Sea Eye' of the Carpathians, is the largest mountain lake in Ukraine, situated at an elevation of 989 meters. It was formed approximately 10,000 years ago following a massive landslide that blocked the flow of a mountain stream. The lake covers an area of up to 7 hectares and reaches a maximum depth of about 24 meters. In the center of the lake lies a small island which, during low water levels, resembles the pupil of an eye, giving the lake its poetic nickname. The water is crystal clear and supports rare brown trout, although its temperature rarely rises above 11 degrees Celsius even in summer. The lake is surrounded by centuries-old fir and beech forests within the Synevyr National Park, established in 1989. A famous local legend tells of the tragic love between a count's daughter, Syn, and a shepherd, Evyr, after whom the lake is said to be named. Today, it is a significant natural monument and a magnet for tourists seeking serene mountain scenery.",
      es: "El lago Synevyr es el lago de montaña más grande de los Cárpatos ucranianos y se encuentra a 989 metros de altitud. Se formó hace unos 10.000 años debido a un enorme deslizamiento de tierra.",
      pt: "O lago Synevyr é o maior lago de montanha dos Cárpatos ucranianos e situa-se a 989 metros de altitude. Formou-se há cerca de 10.000 anos devido a um enorme deslizamento de terra.",
      fr: "Le lac Synevyr est le plus grand lac de montagne des Carpates ukrainiennes et se situe à 989 mètres d'altitude. Il s'est formé il y a environ 10 000 ans à la suite d'un immense glissement de terrain.",
    },
    factsAdvanced: {
      de: ["Größter Bergsee der ukrainischen Karpaten auf 989 m Höhe.", "Entstand durch einen Erdrutsch vor etwa 10.000 Jahren.", "Maximale Tiefe beträgt ca. 24 Meter bei klarem Wasser.", "Wassertemperatur übersteigt selten 11 Grad Celsius.", "Heimat der Bachforelle und anderer kälteliebender Arten.", "Zentrum des Nationalparks Synevyr, gegründet 1989."],
      hu: ["Az Ukrán-Kárpátok legnagyobb hegyi tava 989 méteren.", "Egy földcsuszamlás hozta létre mintegy 10 000 évvel ezelőtt.", "Maximális mélysége körülbelül 24 méter, vize rendkívül tiszta.", "A víz hőmérséklete nyáron sem haladja meg a 11 fokot.", "A sebes pisztráng és más hidegkedvelő fajok élőhelye.", "Az 1989-ben alapított Szinevéri Nemzeti Park központja."],
      ro: ["Cel mai mare lac montan din Carpații Ucraineni la 989 m.", "Format printr-o alunecare de teren acum circa 10.000 de ani.", "Adâncimea maximă este de aproximativ 24 de metri.", "Temperatura apei depășește rar 11 grade Celsius.", "Habitat pentru păstrăvul de munte și alte specii criofile.", "Inima Parcului Național Sinevir, înființat în anul 1989."],
      en: ["Largest mountain lake in the Ukrainian Carpathians at 989 m.", "Formed by a landslide approximately 10,000 years ago.", "Maximum depth is about 24 meters with crystal clear water.", "Water temperature rarely exceeds 11 degrees Celsius.", "Home to brown trout and other cold-loving species.", "Center of the Synevyr National Park, established in 1989."],
      es: ["Superficie: aprox. 7 hectáreas", "Profundidad máxima: 22 metros", "Altitud: 989 metros", "Edad: aprox. 10.000 años"],
      pt: ["Área: aprox. 7 hectares", "Profundidade máxima: 22 metros", "Altitude: 989 metros", "Idade: aprox. 10.000 anos"],
      fr: ["Superficie : env. 7 hectares", "Profondeur maximale : 22 mètres", "Altitude : 989 mètres", "Âge : env. 10 000 ans"],
    },
    image: "/poi-images/ukraine-synevyr-nature-v2.webp",
