      ro: ["Cea mai mare suprafață de nisip din Ucraina, circa 161.000 ha.", "Cuprinde dune mișcătoare cu înălțimi de până la 20 de metri.", "Temperatura solului atinge vara valori de până la 75 de grade.", "Înconjurată de cele mai mari păduri artificiale din lume.", "A servit drept poligon militar de testare în secolul al XX-lea.", "Parcul Național Natural a fost înființat oficial în anul 2010."],
      en: ["Largest sand area in Ukraine, covering about 161,000 hectares.", "Features shifting dunes reaching heights of up to 20 meters.", "Ground temperatures can hit 75 degrees Celsius in summer.", "Surrounded by the largest man-made forests in the world.", "Was used as a military testing ground in the 20th century.", "The National Nature Park was officially established in 2010."],
      es: ["Superficie: 161.000 hectáreas", "Altura de dunas: hasta 20 m", "Temp. estival: más de 45 °C", "Ubicación: Óblast de Jersón"],
