      es: ["Isla más grande de Ucrania", "Longitud de 42 kilómetros", "Situada en el Mar Negro", "Hogar de ciervos y muflones"],
      pt: ["Maior ilha da Ucrânia", "Comprimento de 42 quilômetros", "Localizada no Mar Negro", "Lar de veados e muflões"],
