      de: "Der Nationalpark Tusly-Lagunen umfasst eine Kette von Salzlagunen an der Küste des Schwarzen Meeres. Er ist ein wichtiges Rastgebiet für Zugvögel.",
      hu: "A Tuzlai-lagúnák Nemzeti Park sós lagúnák láncolatát foglalja magában a Fekete-tenger partján. Fontos pihenőhely a költöző madarak számára.",
      ro: "Parcul Național Lagunele Tuzla cuprinde un lanț de lagune sărate pe coasta Marii Negre. Este o zonă crucială de popas pentru păsările migratoare.",
      en: "Tuzly Lagoons National Nature Park encompasses a chain of salt lagoons along the Black Sea coast. It is a vital stopover for migratory birds.",
      es: "El Parque Nacional de las Lagunas de Tuzly comprende una cadena de lagunas saladas en la costa del Mar Negro. Es una importante zona de descanso para aves migratorias.",
      pt: "O Parque Nacional das Lagoas de Tuzly compreende uma cadeia de lagoas salgadas na costa do Mar Negro. É uma importante área de repouso para aves migratórias.",
      fr: "Le parc national des lagunes de Touzly comprend une chaîne de lagunes salées sur la côte de la mer Noire. C'est une zone de repos importante pour les oiseaux migrateurs.",
