      hu: ["Teljes hossza 806 kilométer", "Csak Ukrajna területén folyik", "Népszerű rafting helyszín", "A Dnyeper-Bug limánba torkollik"],
      ro: ["Lungime totală de 806 kilometri", "Curge exclusiv în Ucraina", "Popular pentru rafting", "Se varsă în Limanul Nipru-Bug"],
