    image: "/poi-images/ukraine-aktove-canyon-nature-v2.webp",
    coords: [31.4647, 47.7128],
    coords: [31.4647, 47.7128],
    description: {
      de: "Der Aktowe-Canyon wird wegen seiner bizarren Felsformationen oft als 'Teufelsschlucht' bezeichnet. Er liegt in der Oblast Mykolajiw und ist Teil des Granit-Steppen-Gebiets.",
      hu: "Az Aktove-kanyont bizarr sziklaalakzatai miatt gyakran 'Ördög-szurdoknak' nevezik. A Mikolajivi területen található, és a gránit-sztyeppei vidék része.",
      ro: "Canionul Aktove este adesea numit 'Canionul Diavolului' datorită formațiunilor stâncoase bizare. Este situat în regiunea Nikolaev.",
      en: "Aktove Canyon is often called 'Devil's Canyon' due to its bizarre rock formations. It is located in the Mykolaiv region and is part of a granite-steppe area.",
    },
    facts: {
      de: ["Besteht aus 4 Milliarden Jahre altem Granit", "Tiefe von bis zu 50 Metern", "Teil des Nationalparks Buskyj Hard", "Einzigartiges Ökosystem in der Steppe"],
      hu: ["4 milliárd éves gránitból áll", "Akár 50 méter mély", "A Buzkij Hard Nemzeti Park része", "Egyedülálló ökoszisztéma a sztyeppén"],
      ro: ["Format din granit vechi de 4 miliarde ani", "Adâncime de până la 50 de metri", "Parte a Parcului Național Buzkiy Hard", "Ecosistem unic în zona de stepă"],
      en: ["Composed of 4-billion-year-old granite", "Depth of up to 50 meters", "Part of the Buzkiy Hard National Park", "Unique ecosystem within the steppe"],
    },
imageHint: "Aktove Canyon granite rocks and river",
    descriptionAdvanced: {
      de: "Der Aktowe-Canyon, oft als 'Tal des Teufels' oder 'Kleines Krim' bezeichnet, liegt im Rajon Wosnessensk der Oblast Mykolajiw am Fluss Mertwowid. Diese geologische Formation ist Teil des Nationalparks 'Bug-Gard' und erstreckt sich über eine Fläche von etwa 250 Hektar. Die Schlucht entstand durch das Einschneiden des Flusses in die harten Granitfelsen des Ukrainischen Schildes, wodurch bis zu 50 Meter hohe, fast senkrechte Wände entstanden sind. Die Landschaft erinnert stark an die Canyons in Nordamerika und stellt eine ökologische Besonderheit in der ansonsten flachen Steppenlandschaft dar. Die zerklüfteten Felsen und tiefen Schluchten beherbergen eine einzigartige Mikrowelt mit seltenen Pflanzenarten und Reptilien. Historisch gesehen war der Ort für die Skythen von spiritueller Bedeutung, die ihre Könige im nahegelegenen Tal bestatteten. Heute ist der Aktowe-Canyon ein beliebtes Ziel für Kletterer, Fotografen und Wanderer, die die unberührte Natur und die dramatischen Felsformationen schätzen.",
      hu: "Az Aktove-kanyon, amelyet gyakran az 'Ördög völgyeként' is emlegetnek, a Mikolajiv területen található, a Mertvovid folyó mentén. Ez a lenyűgöző természeti képződmény a 'Bug-Gárd' Nemzeti Park része, és mintegy 250 hektáros területet foglal el. A kanyon falai helyenként elérik az 50 méteres magasságot, és az ősi Ukrán-pajzs kemény gránitszikláiból állnak, amelyek több milliárd évesek. A táj éles ellentétben áll a környező sík sztyeppével, és geomorfológiailag hasonlít az észak-amerikai kanyonokhoz. A terület egyedi mikroklímával rendelkezik, amely lehetővé teszi ritka növények és állatok túlélését a sziklák között. A legenda szerint a Mertvovid (Holt víz) folyó onnan kapta a nevét, hogy a szkíták ezen a vidéken bocsátották utolsó útjukra királyaikat. Napjainkban a kanyon a sziklamászók, a természetfotósok és a vadkempingezők kedvelt célpontja, akik a civilizációtól távol eső, érintetlen szépséget keresik.",
      ro: "Canionul Aktove, cunoscut și sub numele de 'Valea Diavolului', este o formațiune geologică spectaculoasă situată în regiunea Mîkolaiv, de-a lungul râului Mertvovîd. Canionul face parte din Parcul Național 'Bugski Gard' și acoperă o suprafață de aproximativ 250 de hectare, având pereți de granit care ating înălțimi de 40-50 de metri. Această structură geologică este unică în Europa, asemănându-se ca relief cu faimoasele canioane din America de Nord, datorită blocurilor masive de piatră sculptate de eroziune. Rocile de aici fac parte din Scutul Ucrainean și au o vechime estimată la câteva miliarde de ani. Microclimatul din interiorul canionului permite dezvoltarea unei flore rare, inclusiv specii de licheni și plante care nu se regăsesc în zonele de stepă învecinate. Istoric, zona a fost sacră pentru sciți, care foloseau râul Mertvovîd pentru ritualuri funerare regale. Astăzi, canionul este o destinație de top pentru alpinism, fotografie de peisaj și turism ecologic în sudul Ucrainei.",
      en: "Aktove Canyon, frequently referred to as the 'Devil's Valley' or 'Small Crimea,' is a breathtaking geological formation located along the Mertvovid River in the Mykolaiv Oblast. Spanning approximately 250 hectares, the canyon is an integral part of the 'Buzkyi Hard' National Nature Park. Its landscape is defined by massive granite cliffs that rise up to 50 meters high, carved out of the ancient crystalline rocks of the Ukrainian Shield over billions of years. The rugged terrain creates a stark contrast with the surrounding flat steppe, bearing a striking resemblance to the canyons of North America. This natural monument hosts a unique micro-ecosystem, providing a habitat for rare plant species and various reptiles nestled among the stone crevices. Historically, the area held great spiritual significance for the Scythians, who reportedly performed royal burial rites in the vicinity of the Mertvovid (Dead Water) River. Currently, Aktove Canyon is a magnet for rock climbers, landscape photographers, and hikers seeking a wild and untouched environment.",
    },
    factsAdvanced: {
      de: ["Die Felswände des Canyons erreichen eine Höhe von bis zu 50 Metern.", "Der Canyon erstreckt sich über eine Fläche von rund 250 Hektar.", "Das Alter der Granitfelsen wird auf etwa 4 Milliarden Jahre geschätzt.", "Der Canyon liegt am Fluss Mertwowid, einem Nebenfluss des Südlichen Bug.", "Es ist der einzige Ort in Europa, der geologisch den Canyons von Nordamerika ähnelt.", "Die Region beherbergt über 90 verschiedene Pflanzenarten."],
      hu: ["A kanyon falainak maximális magassága eléri az 50 métert.", "A védett terület kiterjedése megközelítőleg 250 hektár.", "A gránitsziklák kora meghaladja a 4 milliárd évet.", "A Mertvovid folyó kanyargós medre hozta létre a szurdokot.", "A terület 2010 óta a 'Bug-Gárd' Nemzeti Park része.", "A kanyon mikroklímája eltér a környező sztyeppei éghajlattól."],
      ro: ["Pereții canionului au o înălțime cuprinsă între 40 și 50 de metri.", "Suprafața canionului este de aproximativ 250 de hectare.", "Rocile de granit din canion au o vechime de peste 4 miliarde de ani.", "Râul Mertvovîd care traversează canionul este un afluent al Bugului de Sud.", "Canionul Aktove este considerat un monument geologic de importanță europeană.", "Flora canionului include specii rare protejate prin Cartea Roșie a Ucrainei."],
      en: ["The granite cliffs of the canyon reach heights of up to 50 meters.", "The canyon covers a total area of about 250 hectares.", "The geological age of the rocks is estimated at approximately 4 billion years.", "It was formed by the erosion caused by the Mertvovid River.", "The canyon is part of the larger Buzkyi Hard National Nature Park.", "It is the only site in Europe with a landscape similar to North American canyons."],
    },
    image: "/poi-images/ukraine-aktove-canyon-nature-v2.webp",
