      en: ["Ranked as Europe's second-largest river delta", "About 20% of the delta lies within Ukraine", "Chilia branch carries over 50% of the total water volume", "Habitat for more than 300 distinct bird species", "Listed as a UNESCO World Heritage site since 1991", "Home to Vylkove, known as the 'Venice of Ukraine'"],
      es: ["Superficie total: 4152 km²", "Estatus: Patrimonio de la UNESCO", "Especies de aves: > 300", "Ubicación: Óblast de Odesa"],
      pt: ["Área total: 4152 km²", "Estatuto: Património da UNESCO", "Espécies de aves: > 300", "Localização: Oblast de Odessa"],
