imageHint: "Kinburn Spit sandy beach and sea",
    descriptionAdvanced: {
      de: "Die Kinburn-Halbinsel ist eine sandige Landzunge zwischen dem Dnepr-Bug-Liman und dem Schwarzen Meer im Süden der Ukraine. Sie erstreckt sich über eine Länge von etwa 40 Kilometern und ist bekannt für ihre unberührte Natur, die im Nationalpark 'Biloberezhja Swjatoslawa' geschützt ist. Die Landschaft ist ein Mosaik aus Steppenvegetation, Salzseen, kleinen Eichenhainen und ausgedehnten Sandstränden. Historisch war die Halbinsel ein strategisch wichtiger Punkt, an dem 1787 eine berühmte Schlacht während des Russisch-Türkischen Krieges stattfand. Kinburn ist zudem ein bedeutender Rastplatz für Zugvögel und beherbergt eines der größten wilden Orchideenfelder Europas, das im Mai in voller Blüte steht. Aufgrund der fehlenden asphaltierten Straßen und der Abgeschiedenheit hat sich hier ein einzigartiges Ökosystem erhalten, das Lebensraum für seltene Tierarten wie den Steppenwolf und zahlreiche Pelikanarten bietet. Die Gewässer rund um die Spitze sind zudem für ihre Vorkommen von Schweinswalen und Delfinen bekannt.",
      hu: "A Kinburn-félsziget egy keskeny, homokos földnyelv a Dnyeper-Bug torkolat és a Fekete-tenger között, Ukrajna Mikolajivi területén. A mintegy 40 kilométer hosszan elnyúló terület különlegessége az érintetlen természeti környezet, amelyet a „Szvjatoszlav Fehér Partja” Nemzeti Park védelmez. A tájképet sós tavak, homokdűnék, árvalányhajas sztyeppék és apró, reliktum tölgyerdők váltakozása határozza meg. Történelmi szempontból is jelentős helyszín, hiszen 1787-ben itt zajlott a kinburni csata, ahol az orosz csapatok vereséget mértek a török flottára. A félsziget élővilága rendkívül gazdag: tavasszal itt virágzik Európa egyik legnagyobb vadon élő orchideamezeje, amely több tucat hektáron terül el. A terület fontos állomása a madárvonulási útvonalaknak, ahol pelikánok, gémek és darvak ezrei pihennek meg. A nehéz megközelíthetőség és az aszfaltozott utak hiánya miatt a félsziget megőrizte vadregényes jellegét, így a biológiai sokféleség egyik utolsó bástyája a régióban.",
      ro: "Grindul Kinburn este o fâșie îngustă de pământ situată între estuarul Nipru-Bug și Marea Neagră, în regiunea Mîkolaiv din sudul Ucrainei. Cu o lungime de aproximativ 40 de kilometri, această peninsulă este faimoasă pentru natura sa sălbatică, protejată în cadrul Parcului Național „Biloberezhia Sviatoslava”. Peisajul este format dintr-un amestec de dune de nisip, lacuri sărate, stepe și mici păduri de stejar care supraviețuiesc în condiții aride. Din punct de vedere istoric, Kinburn a fost scena unei bătălii navale importante în 1787, fiind un punct strategic de control al navigației spre gurile Niprului. Zona este un refugiu vital pentru biodiversitate, adăpostind una dintre cele mai mari zone cu orhidee sălbatice din Europa și mii de păsări migratoare, inclusiv pelicani roz. Lipsa infrastructurii rutiere moderne a permis conservarea unui ecosistem fragil, unde se pot întâlni specii rare de animale și plante adaptate la solurile nisipoase și salinitatea ridicată a apei.",
      en: "The Kinburn Spit is a sandy peninsula located between the Dnieper-Bug estuary and the Black Sea in southern Ukraine's Mykolaiv region. Stretching for about 40 kilometers, it is renowned for its pristine wilderness, which is legally protected within the Biloberezhia Sviatoslava National Nature Park. The landscape is a mosaic of sand dunes, salt lakes, feather grass steppes, and ancient oak groves known as 'Gilea.' Historically, the spit was a strategic military outpost, most notably serving as the site of a major battle in 1787 during the Russo-Turkish War. Today, it is an ecological treasure, hosting one of Europe's largest fields of wild orchids that bloom spectacularly every May. The area serves as a critical stopover for migratory birds, including pelicans and herons, while the surrounding waters are home to Black Sea dolphins. Its isolation and lack of paved roads have helped preserve a unique ecosystem that remains one of the last truly wild coastal areas in the northern Black Sea region.",
      es: "La península de Kinburn es una lengua arenosa situada entre la desembocadura del Dniéper y el Mar Negro. Destaca por sus orquídeas silvestres y sus lagos salados con propiedades curativas.",
      pt: "A península de Kinburn é uma língua de areia entre a foz do Dniepre e o Mar Negro. É famosa pelas suas orquídeas selvagens e lagos salgados curativos.",
      fr: "La péninsule de Kinburn est une langue de sable située entre l'embouchure du Dniepr et la mer Noire. Elle est connue pour ses orchidées sauvages et ses lacs salés aux vertus curatives.",
    },
