      en: ["Total surface area covers 2,560 square kilometers", "Salinity levels can reach up to 200 parts per thousand", "Pink coloration is caused by Dunaliella salina algae", "Separated from the sea by the 112-km Arabat Spit", "The mud is highly valued for medical therapies", "Designated as a Ramsar wetland of international importance"],
      es: ["Superficie: 2560 km²", "Profundidad: 0,5 - 1 metro", "Salinidad: hasta 87 ‰", "Apodo: Mar Podrido"],
