      de: "Der Probiy-Wasserfall ist ein kraftvoller Kaskadenwasserfall des Flusses Prut mitten in Jaremtsche. Er ist einer der wasserreichsten Wasserfälle der ukrainischen Karpaten.",
      hu: "A Probij-vízesés a Prut folyó erőteljes zúgója Jaremcse központjában. Az Ukrán-Kárpátok egyik legbővizűbb vízesése.",
