    parent: "UA",
    type: "peak",
    name: { de: "Pip Iwan (Marmarosch)", hu: "Pip Iván (Máramaros)", ro: "Pip Ivan (Maramureș)", en: "Pip Ivan Marmaros"},
    image: "/poi-images/ukraine-pip-ivan-marmaros-nature-v2.webp",
    coords: [24.33, 47.925],
    coords: [24.33, 47.925],
    description: {
      de: "Der Pip Iwan Marmarosch liegt an der Grenze zwischen der Ukraine und Rumänien. Er ist der höchste Gipfel der 'Huzulen-Alpen' und bietet alpine Landschaften.",
      hu: "A máramarosi Pip Iván az ukrán-román határon fekszik. A 'Hucul-Alpok' legmagasabb csúcsa, és alpesi tájakkal büszkélkedhet.",
      ro: "Vârful Pip Ivan din Maramureș este situat la granița dintre Ucraina și România. Este cel mai înalt punct din 'Alpii Huțuli'.",
      en: "Pip Ivan Marmaros is located on the border between Ukraine and Romania. It is the highest peak of the 'Hutsul Alps', featuring alpine scenery.",
      es: "El Pip Ivan Marmarosch se encuentra en la frontera entre Ucrania y Rumanía. Es el pico más alto de los 'Alpes Hutsul' y ofrece paisajes alpinos.",
      pt: "O Pip Ivan Marmarosch está localizado na fronteira entre a Ucrânia e a Roménia. É o pico mais alto dos 'Alpes Hutsul' e oferece paisagens alpinas.",
      fr: "Le Pip Ivan Marmarosch se situe à la frontière entre l'Ukraine et la Roumanie. C'est le plus haut sommet des 'Alpes houtsoules', offrant des paysages alpins.",
    },
