      en: ["Ranked as the longest tributary of the Danube", "Forms at Rakhiv via the White and Black Tysa confluence", "Acts as a natural international border for long stretches", "Infamous for rapid and unpredictable flooding cycles", "Critical habitat for the endangered Danube salmon", "Historically vital for the transport of salt and timber"],
      es: ["Longitud: 966 km", "Cuenca hidrográfica: 157.000 km²", "Desembocadura: Danubio (Serbia)", "Fuente: Tisza Negro/Blanco"],
