      pt: ["Altura de 20 metros", "Localizada no rio Manyavka", "Situada num desfiladeiro profundo", "Perto da aldeia de Manyava"],
      fr: ["Hauteur de 20 mètres", "Située sur la rivière Manyavka", "Se trouve dans une gorge profonde", "Proche du village de Manyava"],
